+}
+function exportLink(file, text = 'Baixar CSV') { return `<a class="button" href="/api/export?file=${encodeURIComponent(file)}" download>${icon('download')}${escapeHtml(text)}</a>`; }
+function badge(value) {
+  const all = {open:['Aberta','amber'],resolved:['Resolvida','green'],rejected:['Rejeitada · aberta','red'],closed:['Concluído','green'],informativo:['Informativo','blue'],atencao:['Atenção','amber'],bloqueante:['Bloqueante','red'],draft:['Rascunho','neutral'],approved:['Aprovado','green'],simulated:['Envio simulado','blue'],sent:['Envio simulado','blue'],REGRA:['Regra','green'],HUMANO:['Humano','blue'],IA:['IA','amber'],CHECKOUT:['Checkout','blue'],REMESSA:['Remessa','neutral'],billing:['Cobrança','neutral'],dispute:['Contestação','amber'],internal:['Interno','blue']};
