+  return heading('CENTRAL DE FECHAMENTO','Um mês. Todas as respostas.','Do dado de origem à decisão do analista, em um só lugar.',`${button('Recalcular','recalculate',{icon:'refresh'})}${button(closed() ? 'Reabrir mês' : 'Concluir fechamento',closed() ? 'reopen' : 'close',{class:'primary',icon:'close'})}`)+periodBar()+
+    `<div class="kpi-grid">${kpis.map(([label,value,detail,img,cls]) => `<article class="kpi ${cls}"><div class="kpi-label">${label}${icon(img)}</div><div class="kpi-value">${value}</div><div class="kpi-detail">${detail}</div></article>`).join('')}</div>`+
+    `<div class="overview-grid"><section class="panel"><div class="panel-header"><div><h2>O que precisa de você</h2><p>${count(pending.length)} pendências abertas${blocking.length ? ` · ${count(blocking.length)} bloqueantes` : ''}</p></div><a class="text-link" href="#issues">Ver todas →</a></div><div class="panel-body">${important.length ? important.map(row => `<div class="issue-preview"><div class="issue-severity ${row.severity === 'bloqueante' ? 'red' : ''}">${icon('issues')}</div><div class="issue-preview-content"><h3>${escapeHtml(row.tipo || 'Revisão necessária')}</h3><p>${escapeHtml(row.motivo)}</p><div class="issue-preview-meta">${badge(row.severity)}<span>${escapeHtml(row.quem_decide || 'Analista financeiro')}</span></div></div><button class="icon-button" data-action="review" data-id="${attr(identifier(row))}" aria-label="Revisar ${attr(identifier(row))}">${icon('arrow')}</button></div>`).join('') : empty('Tudo revisado por aqui','Não há pendências abertas nesta competência.')}</div></section>
+    <section class="panel"><div class="panel-header"><div><h2>Seu caminho até o fechamento</h2><p>Controle em cada etapa</p></div></div><div class="panel-body">
+      <div class="step"><div class="step-circle done">✓</div><div><h3>Fontes importadas</h3><p>${array(state.sources).length} arquivos preservados e identificados.</p></div></div>
+      <div class="step"><div class="step-circle ${state.validation?.trace_ok === false ? 'current' : 'done'}">${state.validation?.trace_ok === false ? '2' : '✓'}</div><div><h3>Cálculos com rastro</h3><p>${state.validation?.trace_ok === true ? 'Conferência do rastro aprovada pelo motor.' : state.validation?.trace_ok === false ? 'A integridade do rastro requer atenção.' : 'Consulte as origens e regras de cada resultado.'}</p></div></div>
+      <div class="step"><div class="step-circle ${pending.length ? 'current' : 'done'}">${pending.length ? '3' : '✓'}</div><div><h3>Revisão do analista</h3><p>${pending.length ? `${count(pending.length)} decisões precisam de encaminhamento.` : 'Todas as pendências foram encaminhadas.'}</p></div></div>
